import heapq

def CalculateLatestArrivalTimes(N, M, train_info):
    graph = [[] for _ in range(N)]
    for l, d, k, c, a, b in train_info:
        a -= 1
        b -= 1
        graph[a].append((b, l, d, k, c))

    inf = float('-inf')
    time = [inf] * N
    time[0] = 0
    queue = [(0, 0)]

    while queue:
        tx, x = heapq.heappop(queue)
        tx = -tx
        if time[x] > tx:
            continue
        for y, l, d, k, c in graph[x]:
            if tx > l:
                if l + (k - 1) * d >= tx:
                    ty = tx - (tx - l) % d + c
                else:
                    ty = l + (k - 1) * d + c
                if time[y] < ty:
                    time[y] = ty
                    heapq.heappush(queue, (-ty, y))

    for i in range(1, N):
        ans = time[i]
        if ans == inf:
            ans = "Unreachable"
        print(ans)
